-- ecom: the webhook secret in a Shopify / WooCommerce store's webhook URL is what ecom_store_lookup() resolves to a workspace
-- (it must, a public webhook has no tenant yet). It is 240 bits of randomBytes generated by the server, but nothing in the
-- database stopped two rows from holding the same value, and the lookup breaks ties with ORDER BY org_id LIMIT 1: a collision
-- would hand one workspace's store events to another. Make a routable secret unique across workspaces so the lookup can never be
-- ambiguous (tenancy audit TI-004, defence in depth).
--
-- "Routable" = 16 characters or more: the webhook receiver refuses anything shorter before it ever calls the lookup, so a shorter
-- value can never select a workspace and needs no protection (and test fixtures that use 'x' as a secret keep working).
--
-- Cannot fail a deploy on existing data: if a duplicate somehow exists, that table's index is skipped with a NOTICE naming the count,
-- and a person rotates one of the two secrets (the store's webhook URL changes, which is why this does not do it silently) and
-- creates the index with the same statement.
SELECT set_config('app.privileged', 'on', true);

DO $$
DECLARE
  dupes bigint;
BEGIN
  SELECT count(*) INTO dupes FROM (
    SELECT webhook_secret FROM shopify_integrations WHERE length(webhook_secret) >= 16
    GROUP BY webhook_secret HAVING count(*) > 1
  ) d;
  IF dupes = 0 THEN
    CREATE UNIQUE INDEX IF NOT EXISTS uq_shopify_integrations_webhook_secret
      ON shopify_integrations (webhook_secret) WHERE length(webhook_secret) >= 16;
  ELSE
    RAISE NOTICE 'shopify_integrations has % duplicated routable webhook_secret value(s): unique index NOT created', dupes;
  END IF;

  SELECT count(*) INTO dupes FROM (
    SELECT webhook_secret FROM woocommerce_integrations WHERE length(webhook_secret) >= 16
    GROUP BY webhook_secret HAVING count(*) > 1
  ) d;
  IF dupes = 0 THEN
    CREATE UNIQUE INDEX IF NOT EXISTS uq_woocommerce_integrations_webhook_secret
      ON woocommerce_integrations (webhook_secret) WHERE length(webhook_secret) >= 16;
  ELSE
    RAISE NOTICE 'woocommerce_integrations has % duplicated routable webhook_secret value(s): unique index NOT created', dupes;
  END IF;
END
$$;
